SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, RANK() OVER (PARTITION BY category, brand ORDER BY stock_qty DESC NULLS LAST) AS stock_qty_rank, AVG(stock_qty) OVER (PARTITION BY supplier_id ORDER BY launch_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS stock_qty_avg_2_prior, ROUND(price / SUM(price) OVER (PARTITION BY brand), 4) AS price_share FROM products;
